--- a/src/debounce.ts
+++ b/src/debounce.ts
@@ -1,3 +1,14 @@
+export function debounce<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
+  let timer: ReturnType<typeof setTimeout> | undefined
+
+  return (...args: A) => {
+    if (timer !== undefined) clearTimeout(timer)
+
+    timer = setTimeout(() => {
+      timer = undefined
+      fn(...args)
+    }, ms)
+  }
+}
